using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class PRInspect {
 public static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");public static string Out=>Root+"/Docs/Review/2026-11-13_1F_PropRefinement/";
 public static string Kind(Transform t){if(!t.name.StartsWith("F1_")||!t.parent||!t.parent.name.StartsWith("1F_"))return null;foreach(var k in new[]{"CableReel","ToolCart","Forklift","Press"})if(t.name.Contains("_"+k+"_"))return k;return t.name.EndsWith("_Chair")?"OfficeChair":null;}
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Lod1(){var groups=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>Kind(t)!=null).Select(t=>t.GetComponent<LODGroup>()).ToArray();try{foreach(var g in groups)g.ForceLOD(1);return Run("lod1");}finally{foreach(var g in groups)g.ForceLOD(-1);}}
 public static object Before()=>Run("before");public static object After()=>Run("after");public static object ResumeBefore()=>Run("resume");
 static object Run(string phase){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");bool resume=phase=="resume";if(resume)phase="before";Directory.CreateDirectory(Out+phase);
 if(phase=="before"&&!resume){if(File.Exists(Out+"before_transforms.json"))throw new Exception("Baseline exists");var b=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)+"/Temp/AfterSeconds_PropRefinement_20261113/before";Directory.CreateDirectory(b);File.Copy(s.path,b+"/Level_1F_Factory.unity",false);}
 var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 if(!resume)File.WriteAllText(Out+phase+"_transforms.json",JsonConvert.SerializeObject(ts.Select(t=>new{path=AnimationUtility.CalculateTransformPath(t,null),local=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,json=EditorJsonUtility.ToJson(c)}).ToArray()}),Formatting.Indented));
 var targets=ts.Where(t=>Kind(t)!=null).ToArray();if(!resume)File.WriteAllText(Out+phase+"_inventory.json",JsonConvert.SerializeObject(targets.Select(t=>new{name=t.name,kind=Kind(t),position=V(t.position),rotation=V(t.eulerAngles),scale=V(t.localScale),meshes=t.GetComponentsInChildren<MeshFilter>(true).Select(f=>new{name=f.name,asset=AssetDatabase.GetAssetPath(f.sharedMesh),mesh=f.sharedMesh?f.sharedMesh.name:null,bounds=f.sharedMesh?new[]{V(f.sharedMesh.bounds.min),V(f.sharedMesh.bounds.max)}:null,position=V(f.transform.localPosition),enabled=f.GetComponent<Renderer>()?.enabled,materials=f.GetComponent<Renderer>()?.sharedMaterials.Select(m=>m?m.name:null).ToArray()}).ToArray()}),Formatting.Indented));
 foreach(var g in targets.GroupBy(t=>Kind(t))){var t=g.First();var rr=t.GetComponentsInChildren<Renderer>().Where(r=>r.name.EndsWith("LOD0")&&(phase=="before"?!r.name.StartsWith("FD_"):r.name.StartsWith("PR_"))).ToArray();if(rr.Length==0)rr=t.GetComponentsInChildren<Renderer>().Where(r=>!r.name.StartsWith("FD_")).ToArray();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);float d=Mathf.Max(b.size.x,b.size.y,b.size.z);var target=b.center;var from=target+t.TransformDirection(new Vector3(-.72f,.37f,1.05f))*Mathf.Clamp(d*1.18f,.85f,5.5f);Shot(phase,g.Key,from,target,53);var back=target+t.TransformDirection(new Vector3(1,.28f,-.85f))*Mathf.Clamp(d*1.15f,.85f,5.5f);Shot(phase,g.Key+"_Rear",back,target,53);}
 return new{phase,transforms=ts.Length,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),targets=targets.Select(t=>new{t.name,kind=Kind(t)}).ToArray()};}
 public static void Shot(string phase,string name,Vector3 p,Vector3 target,float fov){var go=new GameObject("TemporaryPropReview"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=fov;c.nearClipPlane=.025f;c.farClipPlane=4500;c.useOcclusionCulling=false;c.allowHDR=true;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;bool async=ShaderUtil.allowAsyncCompilation;Texture2D tex=null;try{ShaderUtil.allowAsyncCompilation=false;c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Out+phase+"/"+name+".jpg",tex.EncodeToJPG(92));}finally{ShaderUtil.allowAsyncCompilation=async;RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
